using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Update a configuration value by key.")]
    public static string UpdateConfig(
        [Description("Configuration key to update")] string key,
        [Description("New value to set")] string value)
    {
        ConfigStore.Values[key] = value;
        return $"Set '{key}' = '{value}'";
    }

    [McpServerTool, Description("Get the current value of a configuration key.")]
    public static string GetConfig(
        [Description("Configuration key to retrieve")] string key)
    {
        return ConfigStore.Values.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found.";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAppSettings()
    {
        return JsonSerializer.Serialize(ConfigStore.Values, new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}

using System.Collections.Concurrent;

/// <summary>
/// Simple in-memory configuration store shared between tools and resources.
/// </summary>
public static class ConfigStore
{
    public static ConcurrentDictionary<string, string> Values { get; } = new(
        new Dictionary<string, string>
        {
            ["app:name"] = "McpWebServer",
            ["app:version"] = "1.0.0",
            ["app:environment"] = "development"
        });
}

